steps.input:
{
 "path": "/home/USER/continual-arc-baselines/.workbench/stage1/HPL-openclaw-luna6-low-ws0/frozen/seen-3/play/users/u097/system/state/workspace/programs/task-44ca7449.py",
 "content": "def transform(grid):
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0])
    from collections import Counter,defaultdict
    bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    pts=defaultdict(list)
    for r,row in enumerate(grid):
        for c,v in enumerate(row):
            if v!=bg: pts[v].append((r,c))
    for color, cells in pts.items():
        # A diagonal pair defines a ray; extend outward from the later endpoint.
        for i,(r1,c1) in enumerate(cells):
            for r2,c2 in cells[i+1:]:
                dr,dc=r2-r1,c2-c1
                if dr==0 or abs(dr)!=abs(dc): continue
                sr=1 if dr>0 else -1
                sc=1 if dc>0 else -1
                r,c=r2+sr,c2+sc
                while 0<=r<h and 0<=c<w:
                    if out[r][c]==bg: out[r][c]=color
                    r+=sr;c+=sc
    return out
"
}

