{
 "path": "/home/USER/continual-arc-baselines/.workbench/stage1/HPL-openclaw-luna6-low-ws0/frozen/seen-3/play/users/u097/system/state/workspace/programs/task-44ca7449.py",
 "content": "def transform(grid):
    # Extend same-colored diagonal line segments from their endpoint(s).
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0])
    from collections import Counter,defaultdict
    bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    pts=defaultdict(list)
    for r,row in enumerate(grid):
        for c,v in enumerate(row):
            if v!=bg: pts[v].append((r,c))
    for color,cells in pts.items():
        # Segments are sparse: identify pair with same diagonal slope; extend their
        # common line along the ray continuing beyond the lower/right or lower/left end.
        for i,(r1,c1) in enumerate(cells):
            for r2,c2 in cells[i+1:]:
                dr,dc=r2-r1,c2-c1
                if dr==0 or abs(dr)!=abs(dc): continue
                # extend each direction from both endpoints, retaining existing pixels
                for r,c,sr,sc in ((r1,c1,-(1 if dr>0 else -1),-(1 if dc>0 else -1)),
                                  (r2,c2,(1 if dr>0 else -1),(1 if dc>0 else -1))):
                    rr,cc=r+sr,c+sc
                    while 0<=rr<h and 0<=cc<w:
                        if out[rr][cc]==bg: out[rr][cc]=color
                        rr+=sr;cc+=sc
    return out
"
}

